import React, { forwardRef, useCallback, useRef } from 'react';
import ArvoButton from '../Button/Button';

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

export const ARVO_MSG_ALERT_DEFAULT_ERROR = 'Form field value is invalid';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export type ArvoMessageAlertType =
  | 'error'
  | 'success'
  | 'warning'
  | 'info'
  | 'neutral'
  | 'block';

export interface ArvoMessageAlertProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, 'role'> {
  /** Semantic type. Drives icon glyph + color via the SCSS pattern. Defaults to `error`. */
  type?: ArvoMessageAlertType;
  /** When true, renders ONLY the 16x16 icon (in-field tooltip-error icon mode). */
  isInline?: boolean;
  /**
   * Alert message. In full mode renders inside `__msg`. In inline mode the prop is
   * NOT rendered visually, but a string value is mirrored to `aria-label` on the
   * root. Non-string ReactNode values fall back to the type-default label.
   */
  message?: React.ReactNode;
  /** Optional o9con icon name override (e.g. `'bell'`, `'star'`). */
  icon?: string | null;
  /**
   * When true AND `isInline=false`, renders the trailing close `ArvoButton`.
   * Ignored when `isInline=true`.
   */
  isDismissable?: boolean;
  /** Callback fired when the close button is clicked. */
  onDismiss?: () => void;
  /** DOM id for `aria-describedby` wiring on the associated form control. */
  id?: string;
  /**
   * ARIA live-region role. When omitted, auto-resolves from `type`:
   * `error|warning|block` -> `'alert'`, `info|success|neutral` -> `'status'`.
   */
  role?: 'alert' | 'status';
  className?: string;
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

const TYPE_DEFAULT_LABEL: Record<ArvoMessageAlertType, string> = {
  error: 'Error',
  success: 'Success',
  warning: 'Warning',
  info: 'Information',
  neutral: 'Notice',
  block: 'Blocked',
};

function resolveRole(type: ArvoMessageAlertType): 'alert' | 'status' {
  return type === 'error' || type === 'warning' || type === 'block'
    ? 'alert'
    : 'status';
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export interface ArvoMessageAlertComponent
  extends React.ForwardRefExoticComponent<
    ArvoMessageAlertProps & React.RefAttributes<HTMLDivElement>
  > {
  defaultErrorMessage: string;
}

const ArvoMessageAlertBase = forwardRef<HTMLDivElement, ArvoMessageAlertProps>(
  function ArvoMessageAlert(
    {
      type = 'error',
      isInline = false,
      message,
      icon,
      isDismissable = false,
      onDismiss,
      id,
      role,
      className,
      ...rest
    },
    forwardedRef,
  ) {
    const internalRef = useRef<HTMLDivElement | null>(null);

    const setRef = useCallback(
      (node: HTMLDivElement | null) => {
        internalRef.current = node;
        if (typeof forwardedRef === 'function') {
          forwardedRef(node);
        } else if (forwardedRef) {
          (forwardedRef as React.MutableRefObject<HTMLDivElement | null>).current = node;
        }
      },
      [forwardedRef],
    );

    const handleDismiss = useCallback(() => {
      const node = internalRef.current;
      if (node) {
        node.dispatchEvent(new CustomEvent('msg-alert:dismiss', { bubbles: true }));
      }
      onDismiss?.();
    }, [onDismiss]);

    const resolvedRole = role ?? resolveRole(type);
    const hasIconOverride = !!icon;
    const showCloseButton = isDismissable && !isInline;

    const classes = [
      'arvo-msg-alert',
      `arvo-msg-alert--${type}`,
      isInline && 'arvo-msg-alert--inline',
      showCloseButton && 'arvo-msg-alert--dismissable',
      hasIconOverride && 'has-icon-override',
      className,
    ]
      .filter(Boolean)
      .join(' ');

    if (isInline) {
      const ariaLabel =
        typeof message === 'string' && message.length > 0
          ? message
          : TYPE_DEFAULT_LABEL[type];

      return (
        <div
          ref={setRef}
          className={classes}
          role={resolvedRole}
          id={id}
          aria-label={ariaLabel}
          {...rest}
        >
          <span className="arvo-msg-alert__ico" aria-hidden="true">
            {icon ? <i className={`o9con o9con-${icon}`} /> : null}
          </span>
        </div>
      );
    }

    return (
      <div
        ref={setRef}
        className={classes}
        role={resolvedRole}
        id={id}
        {...rest}
      >
        <div className="arvo-msg-alert__body">
          <span className="arvo-msg-alert__ico" aria-hidden="true">
            {icon ? <i className={`o9con o9con-${icon}`} /> : null}
          </span>
          <span className="arvo-msg-alert__msg">{message}</span>
        </div>
        {showCloseButton ? (
          <ArvoButton
            className="arvo-msg-alert__close"
            variant="secondary"
            size="sm"
            label="Close"
            onClick={handleDismiss}
          />
        ) : null}
      </div>
    );
  },
);

ArvoMessageAlertBase.displayName = 'ArvoMessageAlert';

export const ArvoMessageAlert = ArvoMessageAlertBase as ArvoMessageAlertComponent;
ArvoMessageAlert.defaultErrorMessage = ARVO_MSG_ALERT_DEFAULT_ERROR;

export default ArvoMessageAlert;
